export class People {
  private readonly service = inject(PeopleService);

  protected readonly grades = GRADES;
  protected readonly people = signal<Person[]>([]);
  protected readonly sheet = signal<string | null>(null);
  protected readonly anchor = signal('');
  protected readonly saving = signal(false);
  protected readonly editing = signal<Person | null>(null);
  protected readonly leader = computed(() => this.people().find((p) => p.rank === 1)?.name ?? null);
  protected readonly totalLoad = computed(() =>
    this.people().reduce((total, p) => total + (p.load ?? 0), 0),
  );
  protected readonly activeCount = computed(() => this.people().filter((p) => p.active).length);
  protected readonly totalEffective = computed(() =>
    this.people().reduce((total, p) => total + (p.effective ?? 0), 0),
  );
  protected readonly topInfluence = computed(() => {
    let top: Person | null = null;
    for (const p of this.people()) {
      if (p.influence === null) continue;
      if (
        top === null ||
        p.influence > top.influence! ||
        (p.influence === top.influence && p.name.localeCompare(top.name) < 0)
      ) {
        top = p;
      }
    }
    return top?.name ?? null;
  });

  protected readonly form = inject(NonNullableFormBuilder).group({
    name: ['', [Validators.required, Validators.pattern(/\S/)]],
    alpha: [null as number | null, [Validators.pattern(/^-?\d+$/)]],
    beta: [null as number | null, [Validators.pattern(/^-?\d+$/)]],
    gamma: [null as number | null, [Validators.pattern(/^-?\d+$/)]],
    grade: [null as Grade | null],
  });

  constructor() {
    this.load();
  }

  protected openSheet(value: string): void {
    const id = value.trim();
    const sheet = id === '' ? null : id;
    this.sheet.set(sheet);
    this.cancelEdit();
    if (sheet === null) {
      this.load();
    } else {
      this.service.openSheet(sheet).subscribe(() => {
        if (this.sheet() === sheet) this.load();
      });
    }
  }

  protected edit(person: Person): void {
    this.editing.set(person);
    this.form.reset({ name: person.name, alpha: person.alpha, beta: person.beta, gamma: person.gamma, grade: person.grade });
    this.form.controls.name.disable();
  }

  protected cancelEdit(): void {
    this.editing.set(null);
    this.form.controls.name.enable();
    this.form.reset();
  }

  protected submit(): void {
    const { name, alpha, beta, gamma, grade } = this.form.getRawValue();
    if (this.form.invalid) return;
    const editing = this.editing();
    const request = editing
      ? this.service.update(this.sheet(), editing.id, { alpha: toNumber(alpha), beta: toNumber(beta), gamma: toNumber(gamma), grade })
      : this.service.add(this.sheet(), { name, alpha, beta, gamma, grade });
    this.saving.set(true);
    request.subscribe({
      next: () => {
        this.saving.set(false);
        this.cancelEdit();
        this.load();
      },
      error: () => this.saving.set(false),
    });
  }

  protected setAlpha(person: Person, value: string): void {
    const text = value.trim();
    if (text !== '' && !/^-?\d+$/.test(text)) return;
    const alpha = text === '' ? null : Number(text);
    this.service.setAlpha(this.sheet(), person.id, alpha).subscribe(() => this.load());
  }

  protected setBeta(person: Person, value: string): void {
    const text = value.trim();
    if (text !== '' && !/^-?\d+$/.test(text)) return;
    const beta = text === '' ? null : Number(text);
    this.service.setBeta(this.sheet(), person.id, beta).subscribe(() => this.load());
  }

  protected setGamma(person: Person, value: string): void {
    const text = value.trim();
    if (text !== '' && !/^-?\d+$/.test(text)) return;
    const gamma = text === '' ? null : Number(text);
    this.service.setGamma(this.sheet(), person.id, gamma).subscribe(() => this.load());
  }

  protected setGrade(person: Person, value: string): void {
    const grade = GRADES.find((g) => g === value) ?? null;
    this.service.setGrade(this.sheet(), person.id, grade).subscribe(() => this.load());
  }

  protected setActive(person: Person, active: boolean): void {
    this.service.setActive(this.sheet(), person.id, active).subscribe(() => this.load());
  }

  protected patronNames(person: Person): string {
    return person.patrons.map((patron) => patron.name).join(', ');
  }

  protected hasPatron(person: Person, other: Person): boolean {
    return person.patrons.some((patron) => patron.id === other.id);
  }

  protected setPatrons(person: Person, select: HTMLSelectElement): void {
    const patronIds = Array.from(select.selectedOptions, (option) => Number(option.value));
    this.service.setPatrons(this.sheet(), person.id, patronIds).subscribe(() => this.load());
  }

  private load(): void {
    const sheet = this.sheet();
    this.service.sheet(sheet).subscribe((s) => {
      if (this.sheet() === sheet) this.anchor.set(s.anchor);
    });
    this.service.list(sheet).subscribe((people) => {
      if (this.sheet() === sheet) this.people.set(people);
    });
  }
}

// A number input's value as a whole number, or null when it is empty.
function toNumber(value: number | string | null): number | null {
  return value === null || value === '' ? null : Number(value);
}
import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, map } from 'rxjs';

export interface Person {
  id: number;
  name: string;
  alpha: number | null;
  beta: number | null;
  gamma: number | null;
  grade: Grade | null;
  weight: number | null;
  thrust: number | null;
  drift: number | null;
  momentum: number | null;
  load: number | null;
  tier: string | null;
  patrons: Patron[];
  backing: number | null;
  net: number | null;
  rank: number | null;
  percentile: number | null;
  onset: string | null;
  age: number | null;
  decay: number | null;
  active: boolean;
  effective: number | null;
  clout: number | null;
  influence: number | null;
}

// A sheet: its id (null for the unnamed sheet) and its anchor date (yyyy-mm-dd; today when none is set).
export interface Sheet {
  id: string | null;
  anchor: string;
}

export type Grade = 'LOW' | 'MID' | 'HIGH';

export const GRADES: readonly Grade[] = ['LOW', 'MID', 'HIGH'];

export interface Patron {
  id: number;
  name: string;
}

export interface NewPerson {
  name: string;
  alpha: number | null;
  beta: number | null;
  gamma: number | null;
  grade: Grade | null;
}

// The people REST API (/api/people).
@Injectable({ providedIn: 'root' })
export class PeopleService {
  private readonly http = inject(HttpClient);

  // The people on a sheet; null is the unnamed sheet.
  list(sheet: string | null): Observable<Person[]> {
    return this.http.get<Person[]>('/api/people', { params: sheetParams(sheet) });
  }

  // A sheet (with its anchor); null is the unnamed sheet.
  sheet(sheet: string | null): Observable<Sheet> {
    return this.http.get<Sheet>('/api/sheet', { params: sheetParams(sheet) });
  }

  // Opens a named sheet, starting a new empty one when no sheet has that id yet.
  openSheet(sheet: string): Observable<void> {
    return this.http.put(`/api/sheets/${encodeURIComponent(sheet)}`, null).pipe(map(() => undefined));
  }

  // Adds a person to a sheet; null is the unnamed sheet.
  add(sheet: string | null, person: NewPerson): Observable<Person> {
    return this.http.post<Person>('/api/people', person, { params: sheetParams(sheet) });
  }

  // Updates the person with an id on a sheet (ids are per sheet); null is the unnamed sheet.
  update(sheet: string | null, id: number, values: Omit<NewPerson, 'name'>): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, values, { params: sheetParams(sheet) });
  }

  setAlpha(sheet: string | null, id: number, alpha: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { alpha }, { params: sheetParams(sheet) });
  }

  setBeta(sheet: string | null, id: number, beta: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { beta }, { params: sheetParams(sheet) });
  }

  setGamma(sheet: string | null, id: number, gamma: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { gamma }, { params: sheetParams(sheet) });
  }

  setGrade(sheet: string | null, id: number, grade: Grade | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { grade }, { params: sheetParams(sheet) });
  }

  setActive(sheet: string | null, id: number, active: boolean): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { active }, { params: sheetParams(sheet) });
  }

  setPatrons(sheet: string | null, id: number, patronIds: number[]): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { patronIds }, { params: sheetParams(sheet) });
  }
}

function sheetParams(sheet: string | null): HttpParams {
  return sheet === null ? new HttpParams() : new HttpParams().set('sheet', sheet);
}

