1	package net.officefloor.hq.app;
2	
3	import java.time.LocalDate;
4	import java.time.format.DateTimeParseException;
5	import java.util.ArrayList;
6	import java.util.LinkedHashMap;
7	import java.util.List;
8	import java.util.Map;
9	import java.util.Set;
10	import net.officefloor.hq.app.people.Grade;
11	import org.springframework.context.annotation.Profile;
12	import org.springframework.http.HttpStatus;
13	import org.springframework.jdbc.core.JdbcTemplate;
14	import org.springframework.transaction.annotation.Transactional;
15	import org.springframework.web.bind.annotation.GetMapping;
16	import org.springframework.web.bind.annotation.PostMapping;
17	import org.springframework.web.bind.annotation.RequestBody;
18	import org.springframework.web.bind.annotation.RequestMapping;
19	import org.springframework.web.bind.annotation.RestController;
20	import org.springframework.web.server.ResponseStatusException;
21	
22	/**
23	 * Per-spec data setup for the end-to-end tests. Profile-guarded so it exists ONLY under the test
24	 * launch (bin/start sets spring.profiles.active=e2e) — never in a real deploy. Tests call these to
25	 * ARRANGE data; they ASSERT only through the UI.
26	 */
27	@Profile("e2e")
28	@RestController
29	@RequestMapping("/__test__")
30	public class TestSupportController {
31	
32	    private static final Set<String> PERSON_FIELDS = Set.of("id", "name", "alpha", "beta", "gamma", "grade", "onset", "active");
33	
34	    private static final Set<String> PATRON_FIELDS = Set.of("personId", "patronId");
35	
36	    private static final Set<String> SHEET_FIELDS = Set.of("id", "anchor", "people", "patrons");
37	
38	    private final Audit audit;
39	    private final JdbcTemplate jdbc;
40	
41	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
42	        this.audit = audit;
43	        this.jdbc = jdbc;
44	    }
45	
46	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
47	    @PostMapping("/reset")
48	    @Transactional
49	    public void reset() {
50	        audit.clear();
51	        // Person is referenced by its patrons, so delete rather than truncate.
52	        jdbc.update("DELETE FROM person_patron");
53	        jdbc.update("DELETE FROM person");
54	        jdbc.update("DELETE FROM sheet");
55	        jdbc.update("DELETE FROM unnamed_sheet");
56	        jdbc.execute("ALTER TABLE person ALTER COLUMN id RESTART WITH 1");
57	    }
58	
59	    /**
60	     * Insert the fixture a spec needs; the payload shape evolves with the schema. Store every field
61	     * given, or refuse with HTTP 400 naming it — never ignore one silently (AGENTS.md §4.2).
62	     */
63	    @PostMapping("/seed")
64	    @Transactional
65	    public void seed(@RequestBody Map<String, Object> fixture) {
66	        for (String key : fixture.keySet()) {
67	            if (!key.equals("anchor") && !key.equals("people") && !key.equals("patrons") && !key.equals("sheets")) {
68	                throw badRequest("unknown fixture key: " + key);
69	            }
70	        }
71	        // The top-level anchor, people and patrons are the unnamed sheet's.
72	        LocalDate anchor = date(fixture.get("anchor"), "anchor");
73	        if (anchor != null) {
74	            jdbc.update("INSERT INTO unnamed_sheet (id, anchor) VALUES (1, ?)", anchor);
75	        }
76	        // People and patrons at the top level are on the unnamed sheet.
77	        seedSheet(null, fixture.get("people"), fixture.get("patrons"), "");
78	        for (Map<String, Object> sheet : rows(fixture.get("sheets"), "sheets")) {
79	            for (String field : sheet.keySet()) {
80	                if (!SHEET_FIELDS.contains(field)) {
81	                    throw badRequest("cannot store sheets." + field);
82	                }
83	            }
84	            if (!(sheet.get("id") instanceof String id) || id.isBlank()) {
85	                throw badRequest("sheets.id is required");
86	            }
87	            jdbc.update("INSERT INTO sheet (id, anchor) VALUES (?, ?)", id, date(sheet.get("anchor"), "sheets.anchor"));
88	            seedSheet(id, sheet.get("people"), sheet.get("patrons"), "sheets.");
89	        }
90	    }
91	
92	    private static String sheetWhere(String sheetId) {
93	        return sheetId == null ? "sheet_id IS NULL" : "sheet_id = ?";
94	    }
95	
96	    private static Object[] sheetArgs(String sheetId, Object... more) {
97	        List<Object> args = new ArrayList<>();
98	        if (sheetId != null) {
99	            args.add(sheetId);
100	        }
101	        args.addAll(List.of(more));
102	        return args.toArray();
103	    }
104	
105	    private long nextLocalId(String sheetId) {
106	        return jdbc.queryForObject("SELECT COALESCE(MAX(local_id), 0) + 1 FROM person WHERE " + sheetWhere(sheetId),
107	                Long.class, sheetArgs(sheetId));
108	    }
109	
110	    /** The internal key of the person with an id on a sheet; refuses an id the sheet does not have. */
111	    private long internalId(String sheetId, long localId, String field) {
112	        List<Long> ids = jdbc.queryForList("SELECT id FROM person WHERE " + sheetWhere(sheetId) + " AND local_id = ?",
113	                Long.class, sheetArgs(sheetId, localId));
114	        if (ids.isEmpty()) {
115	            throw badRequest(field + " " + localId + " is not a person on the sheet");
116	        }
117	        return ids.get(0);
118	    }
119	
120	    /** Inserts one sheet's people and then their patrons; a null sheet id is the unnamed sheet. */
121	    private void seedSheet(String sheetId, Object peopleRows, Object patronRows, String prefix) {
122	        for (Map<String, Object> row : rows(peopleRows, prefix + "people")) {
123	            for (String field : row.keySet()) {
124	                if (!PERSON_FIELDS.contains(field)) {
125	                    throw badRequest("cannot store " + prefix + "people." + field);
126	                }
127	            }
128	            if (!(row.get("name") instanceof String name)) {
129	                throw badRequest(prefix + "people.name is required");
130	            }
131	            Integer alpha = integer(row.get("alpha"), prefix + "people.alpha");
132	            Integer beta = integer(row.get("beta"), prefix + "people.beta");
133	            Integer gamma = integer(row.get("gamma"), prefix + "people.gamma");
134	            String grade = grade(row.get("grade"), prefix + "people.grade");
135	            LocalDate onset = date(row.get("onset"), prefix + "people.onset");
136	            Boolean active = bool(row.get("active"), prefix + "people.active");
137	            // A person's id is their id within the sheet; the internal key is generated.
138	            Integer localId = integer(row.get("id"), prefix + "people.id");
139	            jdbc.update("INSERT INTO person (sheet_id, local_id, name, alpha, beta, gamma, grade, onset, active) "
140	                    + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
141	                    sheetId, localId != null ? localId : nextLocalId(sheetId), name, alpha, beta, gamma, grade, onset,
142	                    active != null ? active : true);
143	        }
144	        // Patrons link people by id, so add them once every person exists.
145	        for (Map<String, Object> row : rows(patronRows, prefix + "patrons")) {
146	            for (String field : row.keySet()) {
147	                if (!PATRON_FIELDS.contains(field)) {
148	                    throw badRequest("cannot store " + prefix + "patrons." + field);
149	                }
150	            }
151	            Integer personId = integer(row.get("personId"), prefix + "patrons.personId");
152	            Integer patronId = integer(row.get("patronId"), prefix + "patrons.patronId");
153	            if (personId == null || patronId == null) {
154	                throw badRequest(prefix + "patrons rows need personId and patronId");
155	            }
156	            jdbc.update("INSERT INTO person_patron (person_id, patron_id) VALUES (?, ?)",
157	                    internalId(sheetId, personId, prefix + "patrons.personId"),
158	                    internalId(sheetId, patronId, prefix + "patrons.patronId"));
159	        }
160	    }
161	
162	    /**
163	     * Read back what is stored, in the same shape and with the same field names the fixtures use,
164	     * so earlier checkpoints' test data can be replayed and checked (AGENTS.md §4.3, §4.4). The
165	     * unnamed sheet's people are at the top level; each named sheet nests its own.
166	     */
167	    @GetMapping("/fixture")
168	    public Map<String, Object> fixture() {
169	        Map<String, Object> out = new LinkedHashMap<>();
170	        for (String anchor : jdbc.queryForList("SELECT CAST(anchor AS VARCHAR) FROM unnamed_sheet WHERE anchor IS NOT NULL",
171	                String.class)) {
172	            out.put("anchor", anchor);
173	        }
174	        out.putAll(sheetContents(null));
175	        List<Map<String, Object>> sheets = new ArrayList<>();
176	        for (Map<String, Object> row : jdbc.queryForList("SELECT id, CAST(anchor AS VARCHAR) AS anchor FROM sheet ORDER BY id")) {
177	            Map<String, Object> sheet = new LinkedHashMap<>();
178	            sheet.put("id", row.get("id"));
179	            if (row.get("anchor") != null) {
180	                sheet.put("anchor", row.get("anchor"));
181	            }
182	            String id = (String) row.get("id");
183	            sheet.putAll(sheetContents(id));
184	            sheets.add(sheet);
185	        }
186	        out.put("sheets", sheets);
187	        return out;
188	    }
189	
190	    private Map<String, Object> sheetContents(String sheetId) {
191	        String where = sheetId == null ? "p.sheet_id IS NULL" : "p.sheet_id = ?";
192	        Object[] args = sheetId == null ? new Object[0] : new Object[] {sheetId};
193	        Map<String, Object> out = new LinkedHashMap<>();
194	        out.put("people", jdbc.queryForList("SELECT local_id AS \"id\", name AS \"name\", alpha AS \"alpha\", "
195	                + "beta AS \"beta\", gamma AS \"gamma\", grade AS \"grade\", "
196	                + "CAST(onset AS VARCHAR) AS \"onset\", active AS \"active\" FROM person p WHERE " + where + " ORDER BY local_id", args));
197	        out.put("patrons", jdbc.queryForList("SELECT p.local_id AS \"personId\", o.local_id AS \"patronId\" "
198	                + "FROM person_patron pp JOIN person p ON p.id = pp.person_id JOIN person o ON o.id = pp.patron_id "
199	                + "WHERE " + where + " ORDER BY p.local_id, o.local_id", args));
200	        return out;
201	    }
202	
203	    @SuppressWarnings("unchecked")
204	    private static List<Map<String, Object>> rows(Object value, String key) {
205	        if (value == null) {
206	            return List.of();
207	        }
208	        if (!(value instanceof List<?> list) || !list.stream().allMatch(r -> r instanceof Map)) {
209	            throw badRequest(key + " must be a list of rows");
210	        }
211	        return (List<Map<String, Object>>) list;
212	    }
213	
214	    private static Integer integer(Object value, String field) {
215	        if (value == null) {
216	            return null;
217	        }
218	        if (value instanceof Number n && n.doubleValue() == Math.rint(n.doubleValue())) {
219	            return n.intValue();
220	        }
221	        if (value instanceof String s && s.matches("-?\\d+")) {
222	            return Integer.valueOf(s);
223	        }
224	        throw badRequest(field + " must be a whole number, got " + value);
225	    }
226	
227	    private static String grade(Object value, String field) {
228	        if (value == null) {
229	            return null;
230	        }
231	        try {
232	            return Grade.parse(String.valueOf(value)).name();
233	        } catch (IllegalArgumentException e) {
234	            throw badRequest(field + ": " + e.getMessage());
235	        }
236	    }
237	
238	    private static Boolean bool(Object value, String field) {
239	        if (value == null) {
240	            return null;
241	        }
242	        if (value instanceof Boolean b) {
243	            return b;
244	        }
245	        if (value instanceof String s && (s.equals("true") || s.equals("false"))) {
246	            return Boolean.valueOf(s);
247	        }
248	        throw badRequest(field + " must be true or false, got " + value);
249	    }
250	
251	    private static LocalDate date(Object value, String field) {
252	        if (value == null) {
253	            return null;
254	        }
255	        try {
256	            return LocalDate.parse(String.valueOf(value));
257	        } catch (DateTimeParseException e) {
258	            throw badRequest(field + " must be a date as yyyy-mm-dd, got " + value);
259	        }
260	    }
